// Seraph fix (2026-10-13, the owner): supports buff first, then all four start together.
private void SeraphOpener()
{
    string sync = Ultra.ResolveSyncPath("ultra_ezrajal_opener.sync");
    string me = Bot.Player.Username ?? "";
    string cls = Bot.Player.CurrentClass?.Name ?? "";
    bool support = cls == "Lord of Order" || cls == "StoneCrusher";
    Engine.DisableSkills();
    Ultra.UpdateEntry(sync, me, support ? "S0" : "D");
    if (support)
    {
        try
        {
            var acts = Newtonsoft.Json.Linq.JArray.Parse(Bot.Flash.GetGameObject("world.actions.active") ?? "[]");
            for (int i = 1; i < acts.Count && i <= 4; i++)
            {
                string tgt = acts[i]?["tgt"]?.ToString() ?? "";
                if (tgt != "f" && tgt != "s")
                    continue;
                C.Logger($"[Seraph opener] {cls} buffs: {acts[i]?["nam"]}");
                for (int w = 0; w < 10 && !Bot.ShouldExit && !Bot.Skills.CanUseSkill(i); w++)
                    Bot.Sleep(300);
                Engine.Cast(i);
                Bot.Sleep(1600);
            }
        }
        catch (Exception e) { C.Logger($"[Seraph opener] buff failed: {e.Message}"); }
        Ultra.UpdateEntry(sync, me, "S1");
    }
    DateTime start = DateTime.UtcNow;
    while (!Bot.ShouldExit && (DateTime.UtcNow - start).TotalSeconds < 30)
    {
        long now = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
        int fresh = 0, waiting = 0;
        foreach (string line in Ultra.ReadLines(sync))
        {
            string[] p = line.Split(':');
            if (p.Length < 3 || !long.TryParse(p[^1], out long ts) || now - ts > 90)
                continue;
            fresh++;
            if (p[1] == "S0")
                waiting++;
        }
        if (fresh >= 4 && waiting == 0)
            break;
        Bot.Sleep(500);
    }
    C.Logger("[Seraph opener] buffs are up - all four start now");
    Engine.EnableSkills();
}

