// Seraph fix (2026-10-20, vault STRATEGY/Nightbane-Solo): Arcana Invoker solos Nightbane only with its cycle already
// built. Nightbane is a 10-15 s DPS race (10k per-hit cap, 100k Blood Frenzy heals); climbing The Fool -> Judgement
// (~35 s) in front of him is the "endless cycle of death". So: prestack to "XX - Judgement" on the Class Hall Testing
// Dummy, then walk in - the rotation's id 1 on Judgement opens XXI - The World at the boss (lib/skill-overrides.json).
private void SeraphArcanaPrestack()
{
    if (Bot.Player.CurrentClass?.Name != "Arcana Invoker")
        return;
    if (Bot.Self.HasActiveAura("XX - Judgement") || Bot.Self.HasActiveAura("XXI - The World"))
        return;
    Core.Logger("Seraph: Arcana Invoker prestack to XX - Judgement at /classhall before Nightbane");
    Core.Join("classhall");
    string? cell = null;
    foreach (var m in Bot.Monsters.MapMonsters)
        if (m.Name == "Testing Dummy") { cell = m.Cell; break; }
    if (cell == null)
    {
        Core.Logger("Seraph prestack: no Testing Dummy in /classhall - fighting from The Fool");
        return;
    }
    Bot.Map.Jump(cell, "Left");
    Bot.Sleep(1500);
    Bot.Skills.Stop();
    System.DateTime end = System.DateTime.Now.AddSeconds(120);
    while (!Bot.ShouldExit && System.DateTime.Now < end && !Bot.Self.HasActiveAura("XX - Judgement"))
    {
        if (!Bot.Player.HasTarget)
            Bot.Combat.Attack("Testing Dummy");
        // id 1 starts the cycle (The Fool), then Invocation (id 2) climbs it; Revocation (id 3, 40 mana) and One With
        // the Cycle (id 4) fill the gaps. id 1 is never pressed again here: on the dummy it would reset the cycle.
        int s = !Bot.Self.HasActiveAura("0 - The Fool") ? 1
            : Bot.Skills.CanUseSkill(2) ? 2
            : Bot.Player.Mana >= 40 && Bot.Skills.CanUseSkill(3) ? 3
            : Bot.Skills.CanUseSkill(4) ? 4 : -1;
        if (s > 0 && Bot.Skills.CanUseSkill(s))
            Bot.Skills.UseSkill(s);
        Bot.Sleep(150);
    }
    Bot.Combat.CancelTarget();
    Core.Logger(Bot.Self.HasActiveAura("XX - Judgement")
        ? "Seraph prestack: on XX - Judgement, going to Nightbane"
        : "Seraph prestack: no Judgement after 120 s - fighting from where the cycle is");
}

