// Seraph (2026-10-28, the owner: "dont waste money re-enhancing - equip the items that match whatever the script wants"):
// for every worn weapon / helm / cape that lacks the requested enhancement, an owned item of the same slot that has it
// (backpack first, then bank; the most all-damage first) is put on instead. Classes can't be swapped. Returns true
// when every worn piece (or `only`) now matches.
private bool SeraphWearMatching(EnhancementType type, CapeSpecial cSpecial, HelmSpecial hSpecial, WeaponSpecial wSpecial, InventoryItem? only = null)
{
    if (type == 0)
        return false;
    bool all = true;
    try
    {
        List<InventoryItem> worn = Bot.Inventory.Items.FindAll(i => i.Equipped
            && (i.Category == ItemCategory.Cape || i.Category == ItemCategory.Helm || i.ItemGroup == "Weapon"));
        foreach (InventoryItem cur in worn)
        {
            if (only != null && cur.ID != only.ID)
                continue;
            if (AlreadyHasRequestedEnhancement(cur, type, cSpecial, hSpecial, wSpecial))
                continue;
            bool Same(InventoryItem i) => cur.Category == ItemCategory.Cape ? i.Category == ItemCategory.Cape
                : cur.Category == ItemCategory.Helm ? i.Category == ItemCategory.Helm : i.ItemGroup == "Weapon";
            InventoryItem? pick = Bot.Inventory.Items
                .Where(i => !i.Equipped && Same(i) && AlreadyHasRequestedEnhancement(i, type, cSpecial, hSpecial, wSpecial))
                .OrderByDescending(SeraphAllDamage).FirstOrDefault()
                ?? Bot.Bank.Items
                .Where(i => Same(i) && AlreadyHasRequestedEnhancement(i, type, cSpecial, hSpecial, wSpecial))
                .OrderByDescending(SeraphAllDamage).FirstOrDefault();
            if (pick == null)
            {
                all = false;
                continue;
            }
            if (!Bot.Inventory.Contains(pick.Name))
                Core.Unbank(pick.Name);
            Core.Equip(pick.Name);
            Core.Logger($"[Seraph] {cur.Name} -> {pick.Name} (already {type}{(cSpecial != CapeSpecial.None ? "/" + cSpecial : "")}{(hSpecial != HelmSpecial.None ? "/" + hSpecial : "")}{(wSpecial != WeaponSpecial.None ? "/" + wSpecial : "")}) - nothing re-enhanced");
            if (!Bot.Inventory.IsEquipped(pick.Name))
                all = false;
        }
    }
    catch (Exception e)
    {
        Core.Logger($"[Seraph] matching gear: {e.Message}");
        return false;
    }
    return all;
}

private static double SeraphAllDamage(InventoryItem i)
{
    try
    {
        foreach (string part in (i.Meta ?? "").Split(','))
        {
            string[] kv = part.Split(':');
            if (kv.Length == 2 && kv[0].Trim().Equals("dmgAll", StringComparison.OrdinalIgnoreCase)
                && double.TryParse(kv[1], System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out double v))
                return v;
        }
    }
    catch { }
    return 0;
}

